#include "formatter.h"
void *allocate(size_t size) {
    void *data = calloc(1, size ? size : 1);
    if (!data)
        exit(EXIT_FAILURE);
    return data;
}
void *resize(void *data, size_t size) {
    void *next = realloc(data, size ? size : 1);
    if (!next)
        exit(EXIT_FAILURE);
    return next;
}
char *copy_text(const char *text) {
    size_t size = strlen(text) + 1;
    char *out = allocate(size);
    memcpy(out, text, size);
    return out;
}
char *format_text(const char *format, ...) {
    va_list args, copy;
    va_start(args, format);
    va_copy(copy, args);
    int length = vsnprintf(NULL, 0, format, copy);
    va_end(copy);
    if (length < 0)
        exit(EXIT_FAILURE);
    char *out = allocate((size_t)length + 1);
    vsnprintf(out, (size_t)length + 1, format, args);
    va_end(args);
    return out;
}
void lines_push(TextLines *lines, char *text) {
    if (lines->count == lines->capacity) {
        lines->capacity = lines->capacity ? lines->capacity * 2 : 16;
        lines->data = resize(lines->data, (size_t)lines->capacity * sizeof *lines->data);
    }
    lines->data[lines->count++] = text;
}
void lines_add(TextLines *lines, const char *text) { lines_push(lines, copy_text(text)); }
void lines_append(TextLines *lines, const TextLines *from) {
    for (int i = 0; i < from->count; ++i)
        lines_add(lines, from->data[i]);
}
void lines_free(TextLines *lines) {
    for (int i = 0; i < lines->count; ++i)
        free(lines->data[i]);
    free(lines->data);
    *lines = (TextLines){0};
}
TextLines read_lines(const char *path) {
    FILE *input = fopen(path, "rb");
    if (!input)
        exit(EXIT_FAILURE);
    TextLines out = {0};
    char *line = NULL;
    size_t length = 0, capacity = 0;
    int c;
    while ((c = fgetc(input)) != EOF) {
        if (c == '\n') {
            if (!line)
                line = allocate(1);
            line[length] = 0;
            lines_push(&out, line);
            line = NULL;
            length = capacity = 0;
        } else {
            if (length + 1 >= capacity) {
                capacity = capacity ? capacity * 2 : 128;
                line = resize(line, capacity);
            }
            line[length++] = (char)c;
        }
    }
    if (ferror(input))
        exit(EXIT_FAILURE);
    if (length) {
        line[length] = 0;
        lines_push(&out, line);
    } else
        free(line);
    fclose(input);
    return out;
}
char *join_texts(const TextLines *texts, const char *separator) {
    size_t size = 1, separator_size = strlen(separator);
    for (int i = 0; i < texts->count; ++i)
        size += strlen(texts->data[i]) + (i ? separator_size : 0);
    char *out = allocate(size), *at = out;
    for (int i = 0; i < texts->count; ++i) {
        if (i) {
            memcpy(at, separator, separator_size);
            at += separator_size;
        }
        size_t length = strlen(texts->data[i]);
        memcpy(at, texts->data[i], length);
        at += length;
    }
    *at = 0;
    return out;
}

char *repeated(char character, int count) {
    char *out = allocate((size_t)count + 1);
    memset(out, character, (size_t)count);
    out[count] = 0;
    return out;
}
char *trim_right(char *text) {
    size_t length = strlen(text);
    while (length && text[length - 1] == ' ')
        --length;
    text[length] = 0;
    return text;
}

bool word_in(const char *words, const char *word) {
    size_t size = strlen(word);
    const char *at = words;
    while (*at) {
        while (*at == ' ')
            ++at;
        const char *start = at;
        while (*at && *at != ' ')
            ++at;
        if ((size_t)(at - start) == size && !memcmp(start, word, size))
            return true;
    }
    return false;
}
static bool letter(char c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'; }
static bool digit(char c) { return c >= '0' && c <= '9'; }
static char *substring(const char *text, int first, int end) {
    char *out = allocate((size_t)(end - first) + 1);
    memcpy(out, text + first, (size_t)(end - first));
    out[end - first] = 0;
    return out;
}
void comments_push(Comments *comments, Comment *comment) {
    if (comments->count == comments->capacity) {
        comments->capacity = comments->capacity ? comments->capacity * 2 : 8;
        comments->data =
            resize(comments->data, (size_t)comments->capacity * sizeof *comments->data);
    }
    comments->data[comments->count++] = comment;
}
void tokens_push(Tokens *tokens, Token *token) {
    if (tokens->count == tokens->capacity) {
        tokens->capacity = tokens->capacity ? tokens->capacity * 2 : 32;
        tokens->data = resize(tokens->data, (size_t)tokens->capacity * sizeof *tokens->data);
    }
    tokens->data[tokens->count++] = token;
}
static void item_push(Lexed *lexed, Lexeme item) {
    if (lexed->item_count == lexed->item_capacity) {
        lexed->item_capacity = lexed->item_capacity ? lexed->item_capacity * 2 : 64;
        lexed->items = resize(lexed->items, (size_t)lexed->item_capacity * sizeof *lexed->items);
    }
    lexed->items[lexed->item_count++] = item;
}
static void add_token(Lexed *lexed, char *value, TokenKind kind, Position position, int blank) {
    Token *token = allocate(sizeof *token);
    token->value = value;
    token->kind = kind;
    token->position = position;
    token->blank = blank;
    token->index = lexed->tokens.count;
    tokens_push(&lexed->tokens, token);
    item_push(lexed, (Lexeme){token, NULL});
}
static void add_comment(Lexed *lexed, char *value, bool line, Position position, int blank) {
    Comment *comment = allocate(sizeof *comment);
    comment->value = value;
    comment->line = line;
    comment->position = position;
    comment->blank = blank;
    comments_push(&lexed->comments, comment);
    item_push(lexed, (Lexeme){NULL, comment});
}
Lexed lex(const TextLines *source) {
    Lexed out = {0};
    int previous_line = 0;
    for (int row = 0; row < source->count; ++row) {
        const char *line = source->data[row];
        int length = (int)strlen(line);
        for (int at = 0; at < length;) {
            char c = line[at];
            if (c == ' ') {
                ++at;
                continue;
            }
            Position position = {row + 1, at + 1};
            int blank = row > previous_line ? row - previous_line : 0;
            if (at + 1 < length && line[at] == '/' && line[at + 1] == '/') {
                add_comment(&out, trim_right(copy_text(line + at)), true, position, blank);
                previous_line = row + 1;
                break;
            }
            if (at + 1 < length && line[at] == '/' && line[at + 1] == '*') {
                const char *closing = strstr(line + at + 2, "*/");
                if (!closing) {
                    out.error = (FileError){position, copy_text("unterminated comment")};
                    return out;
                }
                int end = (int)(closing - line) + 2;
                add_comment(&out, substring(line, at, end), false, position, blank);
                at = end;
                previous_line = row + 1;
                continue;
            }
            if (letter(c)) {
                int end = at + 1;
                while (end < length && (letter(line[end]) || digit(line[end])))
                    ++end;
                char *value = substring(line, at, end);
                TokenKind kind =
                    word_in(
                        "int float bool string void if else while for return break continue true false switch case default",
                        value)
                        ? TOKEN_KEYWORD
                        : TOKEN_IDENTIFIER;
                add_token(&out, value, kind, position, blank);
                at = end;
                previous_line = row + 1;
                continue;
            }
            if (digit(c)) {
                int end = at + 1;
                while (end < length && digit(line[end]))
                    ++end;
                if (end + 1 < length && line[end] == '.' && digit(line[end + 1])) {
                    end += 2;
                    while (end < length && digit(line[end]))
                        ++end;
                }
                add_token(&out, substring(line, at, end), TOKEN_NUMBER, position, blank);
                at = end;
                previous_line = row + 1;
                continue;
            }
            if (c == '"') {
                int end = at + 1;
                while (end < length && line[end] != '"')
                    end += line[end] == '\\' ? 2 : 1;
                if (end >= length) {
                    out.error = (FileError){position, copy_text("unterminated string")};
                    return out;
                }
                ++end;
                add_token(&out, substring(line, at, end), TOKEN_STRING, position, blank);
                at = end;
                previous_line = row + 1;
                continue;
            }
            if (at + 1 < length) {
                char pair[3] = {line[at], line[at + 1], 0};
                if (word_in("<= >= == != && || += -= *= /= %=", pair)) {
                    add_token(&out, copy_text(pair), TOKEN_SYMBOL, position, blank);
                    at += 2;
                    previous_line = row + 1;
                    continue;
                }
            }
            if (strchr("+-*/%<>=!()[]{},;.?:", c)) {
                add_token(&out, substring(line, at, at + 1), TOKEN_SYMBOL, position, blank);
                ++at;
                previous_line = row + 1;
                continue;
            }
            out.error = (FileError){position, format_text("unexpected character '%c'", c)};
            return out;
        }
    }
    Token *end = allocate(sizeof *end);
    end->value = copy_text("");
    end->kind = TOKEN_END;
    end->position = (Position){source->count + 1, 1};
    end->index = out.tokens.count;
    tokens_push(&out.tokens, end);
    return out;
}
void lex_free(Lexed *lexed) {
    for (int i = 0; i < lexed->tokens.count; ++i) {
        Token *token = lexed->tokens.data[i];
        free(token->value);
        free(token->leading.data);
        free(token->trailing.data);
        free(token);
    }
    for (int i = 0; i < lexed->comments.count; ++i) {
        free(lexed->comments.data[i]->value);
        free(lexed->comments.data[i]);
    }
    free(lexed->tokens.data);
    free(lexed->comments.data);
    free(lexed->items);
    free(lexed->error.message);
}

#include "formatter.h"
static void append_owned(TextLines *to, TextLines *from) {
    for (int i = 0; i < from->count; ++i)
        lines_push(to, from->data[i]);
    free(from->data);
    *from = (TextLines){0};
}
typedef struct {
    int width, indent, max_blank, comment_column;
    bool allman, spaces, keyword_space, indent_cases, add_braces, remove_parens;
} Profile;
typedef struct {
    char name[17];
    Profile profile;
} NamedProfile;
typedef struct {
    char *header;
    char name[33], profile[17];
    TextLines lines;
} Source;
typedef struct {
    TextLines lines;
    FileError error;
    DocPool pool;
    Doc *document, *function_doc;
    char *function_name;
    int comments;
} FormatResult;
static int lexeme_line(Lexeme lexeme) {
    return lexeme.token ? lexeme.token->position.line : lexeme.comment->position.line;
}
static int attach_comments(Lexed *lexed) {
    Token **next = allocate((size_t)lexed->item_count * sizeof *next);
    Token *following = NULL;
    for (int i = lexed->item_count - 1; i >= 0; --i) {
        next[i] = following;
        if (lexed->items[i].token)
            following = lexed->items[i].token;
    }
    Token *previous = NULL;
    int count = 0;
    for (int i = 0; i < lexed->item_count; ++i) {
        Lexeme item = lexed->items[i];
        if (item.token) {
            previous = item.token;
            continue;
        }
        ++count;
        Comment *comment = item.comment;
        Token *token = next[i];
        if (previous && previous->position.line == comment->position.line &&
            (!token || token->position.line > comment->position.line)) {
            comments_push(&previous->trailing, comment);
            previous->original_trailing = true;
        } else {
            comment->own = comment->line || i + 1 == lexed->item_count ||
                           lexeme_line(lexed->items[i + 1]) > comment->position.line;
            if (!token)
                token = lexed->tokens.data[lexed->tokens.count - 1];
            comments_push(&token->leading, comment);
        }
    }
    free(next);
    return count;
}
static void allow_comments(const Node *node, bool *allowed, bool *trailing) {
    if (!node)
        return;
    switch (node->kind) {
    case N_PROGRAM:
        for (int i = 0; i < node->elements.count; ++i)
            allowed[node->elements.data[i]->first] = true;
        break;
    case N_BLOCK:
        allowed[node->close->index] = true;
        for (int i = 0; i < node->elements.count; ++i)
            allowed[node->elements.data[i]->first] = true;
        break;
    case N_SWITCH_BODY:
        allowed[node->close->index] = true;
        for (int i = 0; i < node->elements.count; ++i) {
            const Node *clause = node->elements.data[i];
            allowed[clause->token->index] = true;
            for (int j = 0; j < clause->elements.count; ++j)
                allowed[clause->elements.data[j]->first] = true;
        }
        break;
    case N_IF:
    case N_WHILE:
    case N_FOR:
        if (node->body->kind != N_BLOCK)
            allowed[node->body->first] = true;
        if (node->kind == N_IF && node->else_part && node->else_part->kind != N_BLOCK &&
            node->else_part->kind != N_IF)
            allowed[node->else_part->first] = true;
        break;
    case N_LIST:
        for (int i = 0; i < node->elements.count; ++i)
            allowed[node->elements.data[i]->first] = true;
        if (node->trailing)
            trailing[node->trailing->index] = true;
        break;
    default:
        break;
    }
    Nodes children = node_children(node);
    for (int i = 0; i < children.count; ++i)
        allow_comments(children.data[i], allowed, trailing);
    free(children.data);
}
static FileError check_comments(const Node *root, const Tokens *tokens) {
    bool *allowed = allocate((size_t)tokens->count * sizeof *allowed),
         *trailing = allocate((size_t)tokens->count * sizeof *trailing);
    allowed[tokens->count - 1] = true;
    allow_comments(root, allowed, trailing);
    FileError out = {0};
    for (int i = 0; i < tokens->count && !out.message; ++i) {
        const Token *token = tokens->data[i];
        for (int j = 0; j < token->leading.count; ++j) {
            const Comment *comment = token->leading.data[j];
            if (trailing[token->index] || (comment->own && !allowed[token->index])) {
                out = (FileError){comment->position, copy_text("comment not allowed here")};
                break;
            }
        }
    }
    free(allowed);
    free(trailing);
    return out;
}
typedef struct {
    Profile profile;
    const Tokens *tokens;
    DocPool *pool;
    Doc *first_function;
    const char *function_name;
} Builder;
static Doc *expression(Builder *builder, Node *node, int required);
static Doc *statement(Builder *builder, Node *node);
static Doc *build_list(Builder *builder, Node *node);
static Doc *build_block(Builder *builder, Node *node);
static Doc *body(Builder *builder, Node *node);
static Doc *declaration(Builder *builder, Node *node);
static Doc *simple(Builder *builder, Node *node);
static Doc *space(Builder *builder) {
    return doc_text(builder->pool, builder->profile.spaces ? " " : "");
}
static Doc *operator_line(Builder *builder) {
    return doc_marker(builder->pool, builder->profile.spaces ? D_LINE : D_SOFTLINE);
}
static Doc *keyword_space(Builder *builder) {
    return doc_text(builder->pool, builder->profile.keyword_space ? " " : "");
}
static Doc *brace_separator(Builder *builder) {
    return builder->profile.allman ? doc_marker(builder->pool, D_HARDLINE)
                                   : doc_text(builder->pool, " ");
}
static Doc *separator(Builder *builder, int blank) {
    Docs docs = {0};
    int count = blank < builder->profile.max_blank ? blank : builder->profile.max_blank;
    for (int i = 0; i <= count; ++i)
        docs_push(&docs, doc_marker(builder->pool, D_HARDLINE));
    return doc_cat(builder->pool, docs);
}
static int pre_blank(const Token *token) {
    return token->leading.count ? token->leading.data[0]->blank : token->blank;
}
static Doc *comment_doc(Builder *builder, const Comments *comments, bool has_last, int last_blank) {
    Docs docs = {0};
    for (int i = 0; i < comments->count; ++i) {
        const Comment *comment = comments->data[i];
        docs_push(&docs, doc_text(builder->pool, comment->value));
        bool next = i + 1 < comments->count;
        if (next || has_last)
            docs_push(&docs, comment->own ? separator(builder, next ? comments->data[i + 1]->blank
                                                                    : last_blank)
                                          : doc_text(builder->pool, " "));
    }
    return doc_cat(builder->pool, docs);
}
static Doc *trailing_part(Builder *builder, const Token *token) {
    if (!token->trailing.count)
        return doc_text(builder->pool, "");
    TextLines parts = {0};
    for (int i = 0; i < token->trailing.count; ++i)
        lines_add(&parts, token->trailing.data[i]->value);
    char *joined = join_texts(&parts, " ");
    Doc *out = doc_suffix(builder->pool, joined);
    free(joined);
    lines_free(&parts);
    return out;
}
static Doc *token_leading(Builder *builder, Token *token, const Comments *leading) {
    return concat(builder->pool, 3, comment_doc(builder, leading, true, token->blank),
                  doc_text(builder->pool, token->value), trailing_part(builder, token));
}
static Doc *token_doc(Builder *builder, Token *token) {
    return token ? token_leading(builder, token, &token->leading) : doc_text(builder->pool, "");
}
typedef struct {
    Comments own, inline_comments;
} ClosingComments;
static ClosingComments split_closing(const Token *token) {
    int split = 0;
    for (int i = 0; i < token->leading.count; ++i)
        if (token->leading.data[i]->own)
            split = i + 1;
    ClosingComments out = {0};
    out.own = (Comments){token->leading.data, split, split};
    out.inline_comments = (Comments){token->leading.data ? token->leading.data + split : NULL,
                                     token->leading.count - split, token->leading.count - split};
    return out;
}
static Doc *whole(Builder *builder, Node *root) {
    Docs docs = {0};
    for (int i = 0; i < root->elements.count; ++i) {
        Node *item = root->elements.data[i];
        if (i)
            docs_push(&docs, separator(builder, pre_blank(builder->tokens->data[item->first])));
        Doc *doc = statement(builder, item);
        docs_push(&docs, doc);
        if (item->kind == N_FUNCTION && !builder->first_function) {
            builder->first_function = doc;
            builder->function_name = item->name->value;
        }
    }
    Token *end = builder->tokens->data[builder->tokens->count - 1];
    if (end->leading.count) {
        if (root->elements.count)
            docs_push(&docs, separator(builder, end->leading.data[0]->blank));
        docs_push(&docs, comment_doc(builder, &end->leading, false, 0));
    }
    return doc_cat(builder->pool, docs);
}
static Doc *build_list(Builder *builder, Node *node) {
    DocPool *pool = builder->pool;
    if (!node->elements.count)
        return concat(pool, 2, token_doc(builder, node->open), token_doc(builder, node->close));
    Doc *force = doc_text(pool, "");
    for (int i = node->open->index; i < node->close->index; ++i)
        if (builder->tokens->data[i]->original_trailing) {
            force = doc_marker(pool, D_BREAK_PARENT);
            break;
        }
    Docs inside = {0};
    docs_push(&inside, doc_marker(pool, D_SOFTLINE));
    for (int i = 0; i < node->elements.count; ++i) {
        if (i) {
            docs_push(&inside, token_doc(builder, node->commas.data[i - 1]));
            docs_push(&inside, doc_marker(pool, D_LINE));
        }
        docs_push(&inside, !strcmp(node->value, "arguments")
                               ? expression(builder, node->elements.data[i], 0)
                               : statement(builder, node->elements.data[i]));
    }
    if (!strcmp(node->value, "initializer")) {
        docs_push(&inside, doc_if_break(pool, ",", ""));
        if (node->trailing)
            docs_push(&inside, trailing_part(builder, node->trailing));
    }
    return doc_group(pool, concat(pool, 5, force, token_doc(builder, node->open),
                                  doc_nest(pool, builder->profile.indent, doc_cat(pool, inside)),
                                  doc_marker(pool, D_SOFTLINE), token_doc(builder, node->close)));
}
static Doc *build_block(Builder *builder, Node *node) {
    DocPool *pool = builder->pool;
    ClosingComments comments = split_closing(node->close);
    if (!node->elements.count && !comments.own.count)
        return concat(pool, 2, token_doc(builder, node->open),
                      token_leading(builder, node->close, &comments.inline_comments));
    Docs inside = {0};
    docs_push(&inside, doc_marker(pool, D_HARDLINE));
    for (int i = 0; i < node->elements.count; ++i) {
        Node *child = node->elements.data[i];
        if (i)
            docs_push(&inside, separator(builder, pre_blank(builder->tokens->data[child->first])));
        docs_push(&inside, statement(builder, child));
    }
    if (comments.own.count) {
        if (node->elements.count)
            docs_push(&inside, separator(builder, comments.own.data[0]->blank));
        docs_push(&inside, comment_doc(builder, &comments.own, false, 0));
    }
    return concat(pool, 4, token_doc(builder, node->open),
                  doc_nest(pool, builder->profile.indent, doc_cat(pool, inside)),
                  doc_marker(pool, D_HARDLINE),
                  token_leading(builder, node->close, &comments.inline_comments));
}
static Doc *body(Builder *builder, Node *node) {
    DocPool *pool = builder->pool;
    if (node->kind == N_BLOCK)
        return concat(pool, 2, brace_separator(builder), build_block(builder, node));
    if (builder->profile.add_braces)
        return concat(
            pool, 5, brace_separator(builder), doc_text(pool, "{"),
            doc_nest(pool, builder->profile.indent,
                     concat(pool, 2, doc_marker(pool, D_HARDLINE), statement(builder, node))),
            doc_marker(pool, D_HARDLINE), doc_text(pool, "}"));
    return doc_nest(pool, builder->profile.indent,
                    concat(pool, 2, doc_marker(pool, D_HARDLINE), statement(builder, node)));
}
static Doc *declaration(Builder *builder, Node *node) {
    DocPool *pool = builder->pool;
    Docs docs = {0};
    docs_push(&docs, token_doc(builder, node->token));
    docs_push(&docs, doc_text(pool, " "));
    docs_push(&docs, token_doc(builder, node->name));
    for (int i = 0; i < node->dimensions.count; ++i) {
        Node *dimension = node->dimensions.data[i];
        docs_push(&docs, token_doc(builder, dimension->open));
        if (dimension->expr)
            docs_push(&docs, expression(builder, dimension->expr, 0));
        docs_push(&docs, token_doc(builder, dimension->close));
    }
    if (node->op) {
        docs_push(&docs, space(builder));
        docs_push(&docs, token_doc(builder, node->op));
        docs_push(&docs, space(builder));
        docs_push(&docs, node->init->kind == N_LIST ? build_list(builder, node->init)
                                                    : expression(builder, node->init, 0));
    }
    docs_push(&docs, token_doc(builder, node->semi));
    return doc_cat(pool, docs);
}
static Doc *simple(Builder *builder, Node *node) {
    return node->kind == N_ASSIGNMENT ? concat(builder->pool, 5, expression(builder, node->left, 0),
                                               space(builder), token_doc(builder, node->op),
                                               space(builder), expression(builder, node->right, 0))
                                      : expression(builder, node->expr, 0);
}
static Doc *statement(Builder *builder, Node *node) {
    DocPool *pool = builder->pool;
    switch (node->kind) {
    case N_FUNCTION:
        return concat(pool, 6, token_doc(builder, node->token), doc_text(pool, " "),
                      token_doc(builder, node->name), build_list(builder, node->init),
                      doc_marker(pool, D_HARDLINE), build_block(builder, node->body));
    case N_PARAMETER:
    case N_DECLARATION:
        return declaration(builder, node);
    case N_LIST:
        return build_list(builder, node);
    case N_BLOCK:
        return build_block(builder, node);
    case N_ASSIGNMENT:
    case N_SIMPLE:
        return concat(pool, 2, simple(builder, node), token_doc(builder, node->semi));
    case N_RETURN: {
        Docs docs = {0};
        docs_push(&docs, token_doc(builder, node->token));
        if (node->expr) {
            docs_push(&docs, doc_text(pool, " "));
            docs_push(&docs, expression(builder, node->expr, 0));
        }
        docs_push(&docs, token_doc(builder, node->semi));
        return doc_cat(pool, docs);
    }
    case N_BREAK:
    case N_CONTINUE:
        return concat(pool, 2, token_doc(builder, node->token), token_doc(builder, node->semi));
    case N_WHILE:
        return concat(pool, 6, token_doc(builder, node->token), keyword_space(builder),
                      token_doc(builder, node->open), expression(builder, node->expr, 0),
                      token_doc(builder, node->close), body(builder, node->body));
    case N_FOR: {
        Docs parts = {0};
        if (node->init)
            docs_push(&parts, node->init->kind == N_DECLARATION ? declaration(builder, node->init)
                                                                : simple(builder, node->init));
        docs_push(&parts, token_doc(builder, node->semi));
        if (node->condition) {
            docs_push(&parts, doc_marker(pool, D_LINE));
            docs_push(&parts, expression(builder, node->condition, 0));
        }
        docs_push(&parts, token_doc(builder, node->semi2));
        if (node->update) {
            docs_push(&parts, doc_marker(pool, D_LINE));
            docs_push(&parts, simple(builder, node->update));
        }
        return concat(pool, 6, token_doc(builder, node->token), keyword_space(builder),
                      token_doc(builder, node->open),
                      doc_group(pool, doc_align(pool, doc_cat(pool, parts))),
                      token_doc(builder, node->close), body(builder, node->body));
    }
    case N_IF: {
        Docs docs = {0};
        docs_push(&docs, token_doc(builder, node->token));
        docs_push(&docs, keyword_space(builder));
        docs_push(&docs, token_doc(builder, node->open));
        docs_push(&docs, expression(builder, node->expr, 0));
        docs_push(&docs, token_doc(builder, node->close));
        docs_push(&docs, body(builder, node->body));
        if (node->else_part) {
            docs_push(&docs, !builder->profile.allman &&
                                     (node->body->kind == N_BLOCK || builder->profile.add_braces)
                                 ? doc_text(pool, " ")
                                 : doc_marker(pool, D_HARDLINE));
            docs_push(&docs, token_doc(builder, node->else_token));
            if (node->else_part->kind == N_IF) {
                docs_push(&docs, doc_text(pool, " "));
                docs_push(&docs, statement(builder, node->else_part));
            } else
                docs_push(&docs, body(builder, node->else_part));
        }
        return doc_cat(pool, docs);
    }
    case N_SWITCH: {
        Node *switch_body = node->body;
        ClosingComments comments = split_closing(switch_body->close);
        Doc *head = concat(pool, 7, token_doc(builder, node->token), keyword_space(builder),
                           token_doc(builder, node->open), expression(builder, node->expr, 0),
                           token_doc(builder, node->close), brace_separator(builder),
                           token_doc(builder, switch_body->open));
        if (!switch_body->elements.count && !comments.own.count)
            return concat(pool, 2, head,
                          token_leading(builder, switch_body->close, &comments.inline_comments));
        Docs inside = {0};
        docs_push(&inside, doc_marker(pool, D_HARDLINE));
        for (int i = 0; i < switch_body->elements.count; ++i) {
            Node *clause = switch_body->elements.data[i];
            if (i)
                docs_push(&inside, separator(builder, pre_blank(clause->token)));
            Docs parts = {0};
            docs_push(&parts, token_doc(builder, clause->token));
            if (clause->expr) {
                docs_push(&parts, doc_text(pool, " "));
                docs_push(&parts, expression(builder, clause->expr, 0));
            }
            docs_push(&parts, token_doc(builder, clause->colon));
            if (clause->elements.count) {
                Docs statements = {0};
                docs_push(&statements, doc_marker(pool, D_HARDLINE));
                for (int j = 0; j < clause->elements.count; ++j) {
                    Node *child = clause->elements.data[j];
                    if (j)
                        docs_push(
                            &statements,
                            separator(builder, pre_blank(builder->tokens->data[child->first])));
                    docs_push(&statements, statement(builder, child));
                }
                docs_push(&parts,
                          doc_nest(pool, builder->profile.indent, doc_cat(pool, statements)));
            }
            docs_push(&inside, doc_cat(pool, parts));
        }
        if (comments.own.count) {
            if (switch_body->elements.count)
                docs_push(&inside, separator(builder, comments.own.data[0]->blank));
            docs_push(&inside, comment_doc(builder, &comments.own, false, 0));
        }
        return concat(pool, 4, head,
                      doc_nest(pool, builder->profile.indent_cases ? builder->profile.indent : 0,
                               doc_cat(pool, inside)),
                      doc_marker(pool, D_HARDLINE),
                      token_leading(builder, switch_body->close, &comments.inline_comments));
    }
    default:
        return expression(builder, node, 0);
    }
}
static Node *opening(Builder *builder, Node *node, int required) {
    if (!builder->profile.remove_parens)
        return node;
    while (node->kind == N_PAREN && expression_level(node->expr) >= required &&
           !node->open->leading.count && !node->close->leading.count) {
        Node *inner = node->expr;
        Token *first = builder->tokens->data[inner->first],
              *last = builder->tokens->data[inner->last];
        Comments front = {0};
        for (int i = 0; i < node->open->trailing.count; ++i)
            comments_push(&front, node->open->trailing.data[i]);
        for (int i = 0; i < first->trailing.count; ++i)
            comments_push(&front, first->trailing.data[i]);
        free(first->trailing.data);
        first->trailing = front;
        for (int i = 0; i < node->close->trailing.count; ++i)
            comments_push(&last->trailing, node->close->trailing.data[i]);
        node->open->trailing.count = 0;
        node->close->trailing.count = 0;
        node = inner;
    }
    return node;
}
static bool postfix(const Node *node) {
    return node->kind == N_CALL || node->kind == N_INDEX || node->kind == N_MEMBER;
}
static Doc *postfix_document(Builder *builder, Node *node) {
    if (node->kind == N_CALL)
        return build_list(builder, node->init);
    if (node->kind == N_INDEX)
        return concat(builder->pool, 3, token_doc(builder, node->open),
                      expression(builder, node->expr, 0), token_doc(builder, node->close));
    return concat(builder->pool, 2, token_doc(builder, node->op), token_doc(builder, node->name));
}
static Doc *expression(Builder *builder, Node *original, int required) {
    Node *node = opening(builder, original, required);
    DocPool *pool = builder->pool;
    switch (node->kind) {
    case N_ATOM:
        return token_doc(builder, node->token);
    case N_PAREN:
        return concat(pool, 3, token_doc(builder, node->open), expression(builder, node->expr, 0),
                      token_doc(builder, node->close));
    case N_UNARY:
        return concat(pool, 2, token_doc(builder, node->op), expression(builder, node->expr, 8));
    case N_BINARY: {
        int level = expression_level(node);
        Tokens operators = {0};
        Nodes operands = {0};
        Node *head = node;
        while (head->kind == N_BINARY && expression_level(head) == level) {
            tokens_push(&operators, head->op);
            nodes_push(&operands, head->right);
            head = opening(builder, head->left, level);
        }
        Docs inside = {0};
        for (int i = operators.count - 1; i >= 0; --i) {
            docs_push(&inside, operator_line(builder));
            docs_push(&inside, token_doc(builder, operators.data[i]));
            docs_push(&inside, space(builder));
            docs_push(&inside, expression(builder, operands.data[i], level + 1));
        }
        Doc *out =
            doc_group(pool, concat(pool, 2, expression(builder, head, level),
                                   doc_nest(pool, builder->profile.indent, doc_cat(pool, inside))));
        free(operators.data);
        free(operands.data);
        return out;
    }
    case N_CONDITIONAL: {
        Docs inside = {0};
        Node *current = node;
        for (;;) {
            docs_push(&inside, operator_line(builder));
            docs_push(&inside, token_doc(builder, current->op));
            docs_push(&inside, space(builder));
            docs_push(&inside, expression(builder, current->then_part, 0));
            docs_push(&inside, operator_line(builder));
            docs_push(&inside, token_doc(builder, current->colon));
            docs_push(&inside, space(builder));
            Node *other = opening(builder, current->else_part, 0);
            if (other->kind == N_CONDITIONAL) {
                docs_push(&inside, expression(builder, other->expr, 1));
                current = other;
            } else {
                docs_push(&inside, expression(builder, other, 0));
                break;
            }
        }
        return doc_group(pool,
                         concat(pool, 2, expression(builder, node->expr, 1),
                                doc_nest(pool, builder->profile.indent, doc_cat(pool, inside))));
    }
    case N_CALL:
    case N_INDEX:
    case N_MEMBER: {
        Nodes operations = {0};
        Node *head = node;
        while (postfix(head)) {
            nodes_push(&operations, head);
            head = opening(builder, head->left, 8);
        }
        for (int i = 0; i < operations.count / 2; ++i) {
            Node *value = operations.data[i];
            operations.data[i] = operations.data[operations.count - 1 - i];
            operations.data[operations.count - 1 - i] = value;
        }
        Nodes *segments = allocate((size_t)(operations.count + 1) * sizeof *segments);
        int segment_count = 1;
        for (int i = 0; i < operations.count; ++i) {
            Node *operation = operations.data[i];
            if (operation->kind == N_MEMBER)
                ++segment_count;
            nodes_push(&segments[segment_count - 1], operation);
        }
        int count = 0, first = -1;
        for (int i = 1; i < segment_count; ++i) {
            bool has_call = false;
            for (int j = 0; j < segments[i].count; ++j)
                if (segments[i].data[j]->kind == N_CALL)
                    has_call = true;
            if (has_call) {
                ++count;
                if (first < 0)
                    first = i;
            }
        }
        Docs docs = {0};
        docs_push(&docs, expression(builder, head, 8));
        Doc *out;
        if (count < 2) {
            for (int i = 0; i < operations.count; ++i)
                docs_push(&docs, postfix_document(builder, operations.data[i]));
            out = doc_cat(pool, docs);
        } else {
            for (int i = 0; i < first; ++i)
                for (int j = 0; j < segments[i].count; ++j)
                    docs_push(&docs, postfix_document(builder, segments[i].data[j]));
            Docs inside = {0};
            for (int i = first; i < segment_count; ++i) {
                docs_push(&inside, doc_marker(pool, D_SOFTLINE));
                for (int j = 0; j < segments[i].count; ++j)
                    docs_push(&inside, postfix_document(builder, segments[i].data[j]));
            }
            docs_push(&docs, doc_nest(pool, builder->profile.indent, doc_cat(pool, inside)));
            out = doc_group(pool, doc_cat(pool, docs));
        }
        for (int i = 0; i < segment_count; ++i)
            free(segments[i].data);
        free(segments);
        free(operations.data);
        return out;
    }
    default:
        exit(EXIT_FAILURE);
    }
}
static FormatResult format(const TextLines *source, Profile profile) {
    FormatResult out = {0};
    Lexed lexed = lex(source);
    if (lexed.error.message) {
        out.error = lexed.error;
        lexed.error.message = NULL;
        lex_free(&lexed);
        return out;
    }
    out.comments = attach_comments(&lexed);
    Parser parser = {0};
    parser.tokens = &lexed.tokens;
    Node *root = parse_program(&parser);
    if (parser.error.message) {
        out.error = parser.error;
        parser.error.message = NULL;
        parser_free(&parser);
        lex_free(&lexed);
        return out;
    }
    out.error = check_comments(root, &lexed.tokens);
    if (!out.error.message) {
        Builder builder = {profile, &lexed.tokens, &out.pool, NULL, NULL};
        out.document = whole(&builder, root);
        out.function_doc = builder.first_function;
        if (builder.function_name)
            out.function_name = copy_text(builder.function_name);
        if (root->elements.count || lexed.tokens.data[lexed.tokens.count - 1]->leading.count)
            out.lines = print_doc(out.document, profile.width, profile.comment_column);
    }
    parser_free(&parser);
    lex_free(&lexed);
    return out;
}
static void result_free(FormatResult *result) {
    lines_free(&result->lines);
    free(result->error.message);
    free(result->function_name);
    doc_pool_free(&result->pool);
}
static NamedProfile *read_profiles(int *count) {
    NamedProfile *out = allocate(5 * sizeof *out);
    *count = 0;
    TextLines lines = read_lines("input/style.txt");
    Profile *profile = NULL;
    for (int i = 0; i < lines.count; ++i) {
        char *line = lines.data[i];
        if (!*line)
            continue;
        if (*line == '[') {
            line[strlen(line) - 1] = 0;
            strcpy(out[*count].name, line + 1);
            profile = &out[(*count)++].profile;
            continue;
        }
        char *value = strchr(line, '=');
        *value++ = 0;
        if (!strcmp(line, "width"))
            profile->width = atoi(value);
        else if (!strcmp(line, "indent"))
            profile->indent = atoi(value);
        else if (!strcmp(line, "max_blank_lines"))
            profile->max_blank = atoi(value);
        else if (!strcmp(line, "comment_column"))
            profile->comment_column = atoi(value);
        else if (!strcmp(line, "brace_style"))
            profile->allman = !strcmp(value, "allman");
        else if (!strcmp(line, "space_around_operators"))
            profile->spaces = !strcmp(value, "yes");
        else if (!strcmp(line, "space_after_keyword"))
            profile->keyword_space = !strcmp(value, "yes");
        else if (!strcmp(line, "indent_case_labels"))
            profile->indent_cases = !strcmp(value, "yes");
        else if (!strcmp(line, "add_braces"))
            profile->add_braces = !strcmp(value, "yes");
        else
            profile->remove_parens = !strcmp(value, "yes");
    }
    lines_free(&lines);
    return out;
}
static Source *read_sources(int *count) {
    Source *out = allocate(20 * sizeof *out);
    *count = 0;
    TextLines lines = read_lines("input/sources.txt");
    for (int i = 0; i < lines.count; ++i) {
        char *line = lines.data[i];
        if (!strncmp(line, "=== ", 4)) {
            Source *source = &out[(*count)++];
            source->header = line;
            char *copy = copy_text(line + 4), *separator = strchr(copy, ' ');
            *separator = 0;
            strcpy(source->name, copy);
            strcpy(source->profile, separator + 1);
            free(copy);
        } else
            lines_push(&out[*count - 1].lines, line);
    }
    free(lines.data);
    return out;
}
static void write_lines(const char *name, const TextLines *lines) {
    char *path = format_text("output/%s", name);
    FILE *output = fopen(path, "wb");
    free(path);
    if (!output)
        exit(EXIT_FAILURE);
    for (int i = 0; i < lines->count; ++i)
        if (fputs(lines->data[i], output) == EOF || fputc('\n', output) == EOF)
            exit(EXIT_FAILURE);
    if (fclose(output))
        exit(EXIT_FAILURE);
}
int main(void) {
    int profile_count, source_count;
    NamedProfile *profiles = read_profiles(&profile_count);
    Source *sources = read_sources(&source_count);
    TextLines formatted = {0}, idempotency = {0}, diagnostics = {0}, trees = {0}, changes = {0};
    for (int file = 0; file < source_count; ++file) {
        Source *source = &sources[file];
        Profile profile = {0};
        for (int i = 0; i < profile_count; ++i)
            if (!strcmp(profiles[i].name, source->profile)) {
                profile = profiles[i].profile;
                break;
            }
        FormatResult result = format(&source->lines, profile);
        TextLines original = {0};
        for (int i = 0; i < source->lines.count; ++i)
            lines_push(&original, trim_right(copy_text(source->lines.data[i])));
        lines_add(&formatted, source->header);
        lines_push(&trees, format_text("=== %s", source->name));
        lines_push(&changes, format_text("=== %s", source->name));
        if (result.error.message) {
            FileError error = result.error;
            lines_append(&formatted, &original);
            lines_push(&idempotency, format_text("%s: skipped (syntax error)", source->name));
            lines_push(&diagnostics,
                       format_text("%s:%d:%d: error: %s", source->name, error.position.line,
                                   error.position.column, error.message));
            lines_add(&trees, "syntax error");
            lines_add(&changes, "skipped (syntax error)");
            lines_free(&original);
            result_free(&result);
            continue;
        }
        lines_append(&formatted, &result.lines);
        FormatResult second = format(&result.lines, profile);
        if (second.error.message) {
            FileError error = second.error;
            lines_push(&idempotency,
                       format_text("%s: unstable (second pass: %d:%d: %s)", source->name,
                                   error.position.line, error.position.column, error.message));
        } else {
            int difference = -1, common = result.lines.count < second.lines.count
                                              ? result.lines.count
                                              : second.lines.count;
            for (int i = 0; i < common; ++i)
                if (strcmp(result.lines.data[i], second.lines.data[i])) {
                    difference = i + 1;
                    break;
                }
            if (difference < 0 && result.lines.count != second.lines.count)
                difference = common + 1;
            if (difference < 0)
                lines_push(&idempotency, format_text("%s: stable", source->name));
            else
                lines_push(&idempotency,
                           format_text("%s: unstable at line %d", source->name, difference));
        }
        int longest = 0;
        for (int i = 0; i < result.lines.count; ++i) {
            int length = (int)strlen(result.lines.data[i]);
            if (length > longest)
                longest = length;
            if (length > profile.width)
                lines_push(&diagnostics, format_text("%s:%d: warning: line too long (%d > %d)",
                                                     source->name, i + 1, length, profile.width));
        }
        GroupMetrics metrics = group_metrics(result.document);
        lines_push(
            &trees,
            format_text("metrics lines=%d longest=%d comments=%d groups=%d broken=%d forced=%d",
                        result.lines.count, longest, result.comments, metrics.groups,
                        metrics.broken, metrics.forced));
        if (!result.function_doc)
            lines_add(&trees, "no function");
        else {
            lines_push(&trees, format_text("function %s", result.function_name));
            TextLines doc_lines = doc_tree(result.function_doc, 0);
            append_owned(&trees, &doc_lines);
        }
        TextLines diff = diff_lines(&original, &result.lines);
        append_owned(&changes, &diff);
        lines_free(&original);
        result_free(&result);
        result_free(&second);
    }
    if (!diagnostics.count)
        lines_add(&diagnostics, "no diagnostics");
    mkdir("output", 0755);
    write_lines("formatted.txt", &formatted);
    write_lines("idempotency.txt", &idempotency);
    write_lines("diagnostics.txt", &diagnostics);
    write_lines("doc_tree.txt", &trees);
    write_lines("changes.txt", &changes);
    for (int i = 0; i < source_count; ++i) {
        free(sources[i].header);
        lines_free(&sources[i].lines);
    }
    free(sources);
    free(profiles);
    lines_free(&formatted);
    lines_free(&idempotency);
    lines_free(&diagnostics);
    lines_free(&trees);
    lines_free(&changes);
    return 0;
}

#include "formatter.h"
void nodes_push(Nodes *nodes, Node *node) {
    if (nodes->count == nodes->capacity) {
        nodes->capacity = nodes->capacity ? nodes->capacity * 2 : 8;
        nodes->data = resize(nodes->data, (size_t)nodes->capacity * sizeof *nodes->data);
    }
    nodes->data[nodes->count++] = node;
}
Nodes node_children(const Node *node) {
    Nodes out = {0};
    Node *fields[] = {node->expr, node->left, node->right,     node->then_part, node->else_part,
                      node->body, node->init, node->condition, node->update};
    for (int i = 0; i < 9; ++i)
        if (fields[i])
            nodes_push(&out, fields[i]);
    for (int i = 0; i < node->elements.count; ++i)
        nodes_push(&out, node->elements.data[i]);
    for (int i = 0; i < node->dimensions.count; ++i)
        nodes_push(&out, node->dimensions.data[i]);
    return out;
}
bool type_name(const Token *token) { return word_in("int float bool string void", token->value); }
int precedence(const char *op) {
    if (!strcmp(op, "||"))
        return 1;
    if (!strcmp(op, "&&"))
        return 2;
    if (!strcmp(op, "==") || !strcmp(op, "!="))
        return 3;
    if (word_in("< <= > >=", op))
        return 4;
    if (!strcmp(op, "+") || !strcmp(op, "-"))
        return 5;
    if (word_in("* / %", op))
        return 6;
    return 0;
}
int expression_level(const Node *node) {
    if (node->kind == N_CONDITIONAL)
        return 0;
    if (node->kind == N_BINARY)
        return precedence(node->op->value);
    if (node->kind == N_UNARY)
        return 7;
    return 8;
}
static Node *make_node(Parser *parser, NodeKind kind) {
    Node *out = allocate(sizeof *out);
    out->kind = kind;
    out->value = "";
    nodes_push(&parser->pool.nodes, out);
    return out;
}
static Token *peek(const Parser *parser) {
    int last = parser->tokens->count - 1;
    return parser->tokens->data[parser->position < last ? parser->position : last];
}
static Token *read_token(Parser *parser) {
    Token *out = peek(parser);
    if (parser->position < parser->tokens->count - 1)
        ++parser->position;
    return out;
}
static void fail(Parser *parser, const char *expected) {
    if (parser->error.message)
        return;
    Token *token = peek(parser);
    char *actual =
        token->kind == TOKEN_END ? copy_text("end of file") : format_text("'%s'", token->value);
    parser->error =
        (FileError){token->position, format_text("expected %s, found %s", expected, actual)};
    free(actual);
}
static Token *take(Parser *parser, const char *value) {
    if (strcmp(peek(parser)->value, value)) {
        char *expected = format_text("'%s'", value);
        fail(parser, expected);
        free(expected);
        return peek(parser);
    }
    return read_token(parser);
}
static Token *take_type(Parser *parser) {
    if (!type_name(peek(parser))) {
        fail(parser, "type");
        return peek(parser);
    }
    return read_token(parser);
}
static Token *identifier(Parser *parser) {
    if (peek(parser)->kind != TOKEN_IDENTIFIER) {
        fail(parser, "identifier");
        return peek(parser);
    }
    return read_token(parser);
}
static Node *mark(Parser *parser, Node *node, int start) {
    node->first = start;
    node->last = parser->position - 1 > start ? parser->position - 1 : start;
    return node;
}
static Node *parse_list(Parser *parser, const char *kind, const char *open, const char *close,
                        bool trailing);
static Node *parameter(Parser *parser);
static Node *declaration(Parser *parser, Token *type, Token *name, int start, bool semi);
static Node *initializer(Parser *parser);
static Node *block(Parser *parser);
static Node *statement(Parser *parser);
static Node *simple(Parser *parser);
static Node *expression(Parser *parser);
static Node *binary(Parser *parser, int level);
static Node *unary(Parser *parser);
Node *parse_program(Parser *parser) {
    Node *out = make_node(parser, N_PROGRAM);
    while (!parser->error.message && peek(parser)->kind != TOKEN_END) {
        int start = parser->position;
        Token *type = take_type(parser), *name = identifier(parser);
        if (parser->error.message)
            break;
        if (!strcmp(peek(parser)->value, "(")) {
            Node *node = make_node(parser, N_FUNCTION);
            node->token = type;
            node->name = name;
            node->init = parse_list(parser, "parameters", "(", ")", false);
            node->body = block(parser);
            nodes_push(&out->elements, mark(parser, node, start));
        } else
            nodes_push(&out->elements, declaration(parser, type, name, start, true));
    }
    return out;
}
static Node *parse_list(Parser *parser, const char *kind, const char *open, const char *close,
                        bool trailing) {
    int start = parser->position;
    Node *out = make_node(parser, N_LIST);
    out->value = kind;
    out->open = take(parser, open);
    if (strcmp(peek(parser)->value, close) && !parser->error.message)
        while (!parser->error.message) {
            Node *child = !strcmp(kind, "parameters")    ? parameter(parser)
                          : !strcmp(kind, "initializer") ? initializer(parser)
                                                         : expression(parser);
            nodes_push(&out->elements, child);
            if (strcmp(peek(parser)->value, ","))
                break;
            Token *comma = read_token(parser);
            if (trailing && !strcmp(peek(parser)->value, close)) {
                out->trailing = comma;
                break;
            }
            tokens_push(&out->commas, comma);
        }
    out->close = take(parser, close);
    return mark(parser, out, start);
}
static Node *parameter(Parser *parser) {
    int start = parser->position;
    Node *out = make_node(parser, N_PARAMETER);
    out->token = take_type(parser);
    out->name = identifier(parser);
    while (!parser->error.message && !strcmp(peek(parser)->value, "[")) {
        int begin = parser->position;
        Node *dimension = make_node(parser, N_DIMENSION);
        dimension->open = read_token(parser);
        dimension->close = take(parser, "]");
        nodes_push(&out->dimensions, mark(parser, dimension, begin));
    }
    return mark(parser, out, start);
}
static Node *declaration(Parser *parser, Token *type, Token *name, int start, bool semi) {
    Node *out = make_node(parser, N_DECLARATION);
    out->token = type;
    out->name = name;
    while (!parser->error.message && !strcmp(peek(parser)->value, "[")) {
        int begin = parser->position;
        Node *dimension = make_node(parser, N_DIMENSION);
        dimension->open = read_token(parser);
        if (strcmp(peek(parser)->value, "]"))
            dimension->expr = expression(parser);
        dimension->close = take(parser, "]");
        nodes_push(&out->dimensions, mark(parser, dimension, begin));
    }
    if (!parser->error.message && !strcmp(peek(parser)->value, "=")) {
        out->op = read_token(parser);
        out->init = initializer(parser);
    }
    if (semi)
        out->semi = take(parser, ";");
    return mark(parser, out, start);
}
static Node *initializer(Parser *parser) {
    return !strcmp(peek(parser)->value, "{") ? parse_list(parser, "initializer", "{", "}", true)
                                             : expression(parser);
}
static Node *block(Parser *parser) {
    int start = parser->position;
    Node *out = make_node(parser, N_BLOCK);
    out->open = take(parser, "{");
    while (!parser->error.message && strcmp(peek(parser)->value, "}") &&
           peek(parser)->kind != TOKEN_END)
        nodes_push(&out->elements, statement(parser));
    out->close = take(parser, "}");
    return mark(parser, out, start);
}
static Node *statement(Parser *parser) {
    int start = parser->position;
    Token *token = peek(parser);
    if (!strcmp(token->value, "{"))
        return block(parser);
    if (type_name(token)) {
        Token *type = read_token(parser), *name = identifier(parser);
        return declaration(parser, type, name, start, true);
    }
    Node *out = make_node(parser, N_SIMPLE);
    out->token = read_token(parser);
    if (!strcmp(token->value, "if") || !strcmp(token->value, "while")) {
        out->kind = !strcmp(token->value, "if") ? N_IF : N_WHILE;
        out->open = take(parser, "(");
        out->expr = expression(parser);
        out->close = take(parser, ")");
        if (!parser->error.message)
            out->body = statement(parser);
        if (out->kind == N_IF && !parser->error.message && !strcmp(peek(parser)->value, "else")) {
            out->else_token = read_token(parser);
            out->else_part = statement(parser);
        }
    } else if (!strcmp(token->value, "for")) {
        out->kind = N_FOR;
        out->open = take(parser, "(");
        if (!parser->error.message && strcmp(peek(parser)->value, ";")) {
            if (type_name(peek(parser))) {
                int begin = parser->position;
                Token *type = read_token(parser), *name = identifier(parser);
                out->init = declaration(parser, type, name, begin, false);
            } else
                out->init = simple(parser);
        }
        out->semi = take(parser, ";");
        if (!parser->error.message && strcmp(peek(parser)->value, ";"))
            out->condition = expression(parser);
        out->semi2 = take(parser, ";");
        if (!parser->error.message && strcmp(peek(parser)->value, ")"))
            out->update = simple(parser);
        out->close = take(parser, ")");
        if (!parser->error.message)
            out->body = statement(parser);
    } else if (!strcmp(token->value, "switch")) {
        out->kind = N_SWITCH;
        out->open = take(parser, "(");
        out->expr = expression(parser);
        out->close = take(parser, ")");
        int begin = parser->position;
        Node *body = make_node(parser, N_SWITCH_BODY);
        body->open = take(parser, "{");
        while (!parser->error.message &&
               (!strcmp(peek(parser)->value, "case") || !strcmp(peek(parser)->value, "default"))) {
            int clause_start = parser->position;
            Node *clause = make_node(parser, N_CLAUSE);
            clause->token = read_token(parser);
            if (!strcmp(clause->token->value, "case"))
                clause->expr = expression(parser);
            clause->colon = take(parser, ":");
            while (!parser->error.message && !word_in("case default }", peek(parser)->value) &&
                   peek(parser)->kind != TOKEN_END)
                nodes_push(&clause->elements, statement(parser));
            nodes_push(&body->elements, mark(parser, clause, clause_start));
        }
        body->close = take(parser, "}");
        out->body = mark(parser, body, begin);
    } else if (!strcmp(token->value, "return")) {
        out->kind = N_RETURN;
        if (!parser->error.message && strcmp(peek(parser)->value, ";"))
            out->expr = expression(parser);
        out->semi = take(parser, ";");
    } else if (!strcmp(token->value, "break") || !strcmp(token->value, "continue")) {
        out->kind = !strcmp(token->value, "break") ? N_BREAK : N_CONTINUE;
        out->semi = take(parser, ";");
    } else {
        parser->position = start;
        out = simple(parser);
        out->semi = take(parser, ";");
    }
    return mark(parser, out, start);
}
static Node *simple(Parser *parser) {
    int start = parser->position;
    Node *left = expression(parser), *out = make_node(parser, N_SIMPLE);
    out->expr = left;
    if (!parser->error.message && word_in("= += -= *= /= %=", peek(parser)->value)) {
        out = make_node(parser, N_ASSIGNMENT);
        out->left = left;
        out->op = read_token(parser);
        out->right = expression(parser);
    }
    return mark(parser, out, start);
}
static Node *expression(Parser *parser) {
    int start = parser->position;
    Node *out = binary(parser, 1);
    if (!parser->error.message && !strcmp(peek(parser)->value, "?")) {
        Node *node = make_node(parser, N_CONDITIONAL);
        node->expr = out;
        node->op = read_token(parser);
        node->then_part = expression(parser);
        node->colon = take(parser, ":");
        node->else_part = expression(parser);
        out = mark(parser, node, start);
    }
    return out;
}
static Node *binary(Parser *parser, int level) {
    if (level == 7)
        return unary(parser);
    Node *left = binary(parser, level + 1);
    while (!parser->error.message && precedence(peek(parser)->value) == level) {
        Node *out = make_node(parser, N_BINARY);
        out->left = left;
        out->op = read_token(parser);
        out->right = binary(parser, level + 1);
        out->first = left->first;
        out->last = out->right->last;
        left = out;
    }
    return left;
}
static Node *unary(Parser *parser) {
    int start = parser->position;
    if (parser->error.message) {
        Node *out = make_node(parser, N_ATOM);
        out->token = peek(parser);
        out->first = out->last = start;
        return out;
    }
    if (!strcmp(peek(parser)->value, "-") || !strcmp(peek(parser)->value, "!")) {
        Node *out = make_node(parser, N_UNARY);
        out->op = read_token(parser);
        out->expr = unary(parser);
        return mark(parser, out, start);
    }
    Token *token = peek(parser);
    Node *out;
    if (token->kind == TOKEN_IDENTIFIER || token->kind == TOKEN_NUMBER ||
        token->kind == TOKEN_STRING || !strcmp(token->value, "true") ||
        !strcmp(token->value, "false")) {
        out = make_node(parser, N_ATOM);
        out->token = read_token(parser);
        mark(parser, out, start);
    } else if (!strcmp(token->value, "(")) {
        out = make_node(parser, N_PAREN);
        out->open = read_token(parser);
        out->expr = expression(parser);
        out->close = take(parser, ")");
        mark(parser, out, start);
    } else {
        fail(parser, "expression");
        out = make_node(parser, N_ATOM);
        out->token = token;
        out->first = out->last = start;
        return out;
    }
    while (!parser->error.message) {
        if (!strcmp(peek(parser)->value, "(")) {
            Node *node = make_node(parser, N_CALL);
            node->left = out;
            node->init = parse_list(parser, "arguments", "(", ")", false);
            out = mark(parser, node, start);
        } else if (!strcmp(peek(parser)->value, "[")) {
            Node *node = make_node(parser, N_INDEX);
            node->left = out;
            node->open = read_token(parser);
            node->expr = expression(parser);
            node->close = take(parser, "]");
            out = mark(parser, node, start);
        } else if (!strcmp(peek(parser)->value, ".")) {
            Node *node = make_node(parser, N_MEMBER);
            node->left = out;
            node->op = read_token(parser);
            node->name = identifier(parser);
            out = mark(parser, node, start);
        } else
            break;
    }
    return out;
}
void parser_free(Parser *parser) {
    for (int i = 0; i < parser->pool.nodes.count; ++i) {
        Node *node = parser->pool.nodes.data[i];
        free(node->elements.data);
        free(node->dimensions.data);
        free(node->commas.data);
        free(node);
    }
    free(parser->pool.nodes.data);
    free(parser->error.message);
}

#include "formatter.h"
typedef struct {
    int indent;
    bool flat;
    Doc *doc;
} Command;
typedef struct {
    Command *data;
    int count, capacity;
} Commands;
static void command_push(Commands *commands, Command command) {
    if (commands->count == commands->capacity) {
        commands->capacity = commands->capacity ? commands->capacity * 2 : 64;
        commands->data =
            resize(commands->data, (size_t)commands->capacity * sizeof *commands->data);
    }
    commands->data[commands->count++] = command;
}
static void push_children(Commands *stack, Command command) {
    for (int i = command.doc->children.count - 1; i >= 0; --i)
        command_push(stack, (Command){command.indent, command.flat, command.doc->children.data[i]});
}
static bool fits(int remaining, Command first, const Commands *original) {
    if (remaining < 0)
        return false;
    Commands stack = {0};
    command_push(&stack, first);
    int unused = original->count - 1;
    bool result = true;
    while (stack.count || unused >= 0) {
        if (!stack.count)
            command_push(&stack, original->data[unused--]);
        Command command = stack.data[--stack.count];
        Doc *doc = command.doc;
        bool done = false;
        switch (doc->kind) {
        case D_TEXT:
            remaining -= (int)strlen(doc->value);
            break;
        case D_IF_BREAK:
            remaining -= (int)strlen(command.flat ? doc->other : doc->value);
            break;
        case D_LINE:
            if (!command.flat)
                done = true;
            else
                --remaining;
            break;
        case D_SOFTLINE:
            if (!command.flat)
                done = true;
            break;
        case D_HARDLINE:
            done = true;
            break;
        case D_CONCAT:
            push_children(&stack, command);
            break;
        case D_GROUP:
            command_push(&stack, (Command){command.indent, doc->forced ? false : command.flat,
                                           doc->children.data[0]});
            break;
        case D_NEST:
        case D_ALIGN:
            command_push(&stack, (Command){command.indent, command.flat, doc->children.data[0]});
            break;
        default:
            break;
        }
        if (done)
            break;
        if (remaining < 0) {
            result = false;
            break;
        }
    }
    free(stack.data);
    return result;
}
typedef struct {
    char *data;
    size_t length, capacity;
} LineBuffer;
static void line_add(LineBuffer *line, const char *value) {
    size_t length = strlen(value), size = line->length + length + 1;
    if (size > line->capacity) {
        size_t capacity = line->capacity ? line->capacity : 128;
        while (capacity < size)
            capacity *= 2;
        line->data = resize(line->data, capacity);
        line->capacity = capacity;
    }
    memcpy(line->data + line->length, value, length + 1);
    line->length += length;
}
static void finalize(TextLines *lines, const LineBuffer *current, TextLines *pending, int width,
                     int comment_column) {
    char *line = trim_right(copy_text(current->data ? current->data : ""));
    if (pending->count) {
        char *comments = join_texts(pending, " ");
        size_t length = strlen(line);
        char *spaces = comment_column > 0 && (int)length < comment_column - 1 &&
                               comment_column - 1 + (int)strlen(comments) <= width
                           ? repeated(' ', comment_column - 1 - (int)length)
                           : copy_text(" ");
        char *with_comments = format_text("%s%s%s", line, spaces, comments);
        free(line);
        free(spaces);
        free(comments);
        line = with_comments;
    }
    lines_free(pending);
    lines_push(lines, line);
}
TextLines print_doc(Doc *document, int width, int comment_column) {
    TextLines out = {0}, pending = {0};
    LineBuffer current = {0};
    int column = 0;
    Commands stack = {0};
    command_push(&stack, (Command){0, false, document});
    while (stack.count) {
        Command command = stack.data[--stack.count];
        Doc *doc = command.doc;
        bool newline = false;
        switch (doc->kind) {
        case D_TEXT:
            line_add(&current, doc->value);
            column += (int)strlen(doc->value);
            break;
        case D_IF_BREAK: {
            const char *value = command.flat ? doc->other : doc->value;
            line_add(&current, value);
            column += (int)strlen(value);
            break;
        }
        case D_LINE:
            if (command.flat) {
                line_add(&current, " ");
                ++column;
            } else
                newline = true;
            break;
        case D_SOFTLINE:
            newline = !command.flat;
            break;
        case D_HARDLINE:
            newline = true;
            break;
        case D_CONCAT:
            push_children(&stack, command);
            break;
        case D_NEST:
            command_push(&stack, (Command){command.indent + doc->number, command.flat,
                                           doc->children.data[0]});
            break;
        case D_ALIGN:
            command_push(&stack, (Command){column, command.flat, doc->children.data[0]});
            break;
        case D_SUFFIX:
            lines_add(&pending, doc->value);
            break;
        case D_GROUP: {
            bool flat = true;
            doc->mode = MODE_FLAT;
            if (!command.flat) {
                if (doc->forced) {
                    flat = false;
                    doc->mode = MODE_FORCED;
                } else if (!fits(width - column,
                                 (Command){command.indent, true, doc->children.data[0]}, &stack)) {
                    flat = false;
                    doc->mode = MODE_BREAK;
                }
            }
            command_push(&stack, (Command){command.indent, flat, doc->children.data[0]});
            break;
        }
        default:
            break;
        }
        if (newline) {
            finalize(&out, &current, &pending, width, comment_column);
            current.length = 0;
            if (current.data)
                current.data[0] = 0;
            char *indent = repeated(' ', command.indent);
            line_add(&current, indent);
            free(indent);
            column = command.indent;
        }
    }
    finalize(&out, &current, &pending, width, comment_column);
    free(current.data);
    free(stack.data);
    return out;
}

#include "formatter.h"
static void append_owned(TextLines *to, TextLines *from) {
    for (int i = 0; i < from->count; ++i)
        lines_push(to, from->data[i]);
    free(from->data);
    *from = (TextLines){0};
}
TextLines doc_tree(const Doc *doc, int depth) {
    char *prefix = repeated(' ', 2 * depth);
    TextLines out = {0};
    switch (doc->kind) {
    case D_TEXT:
        lines_push(&out, format_text("%stext \"%s\"", prefix, doc->value));
        break;
    case D_SUFFIX:
        lines_push(&out, format_text("%ssuffix \"%s\"", prefix, doc->value));
        break;
    case D_IF_BREAK:
        lines_push(&out, format_text("%sif_break \"%s\" \"%s\"", prefix, doc->value, doc->other));
        break;
    case D_LINE:
        lines_push(&out, format_text("%sline", prefix));
        break;
    case D_SOFTLINE:
        lines_push(&out, format_text("%ssoftline", prefix));
        break;
    case D_HARDLINE:
        lines_push(&out, format_text("%shardline", prefix));
        break;
    case D_BREAK_PARENT:
        lines_push(&out, format_text("%sbreak_parent", prefix));
        break;
    case D_CONCAT:
        for (int i = 0; i < doc->children.count; ++i) {
            TextLines child = doc_tree(doc->children.data[i], depth);
            append_owned(&out, &child);
        }
        break;
    default: {
        if (doc->kind == D_GROUP)
            lines_push(&out, format_text("%sgroup %s", prefix,
                                         doc->mode == MODE_FLAT    ? "flat"
                                         : doc->mode == MODE_BREAK ? "break"
                                                                   : "forced"));
        else if (doc->kind == D_NEST)
            lines_push(&out, format_text("%snest %d", prefix, doc->number));
        else
            lines_push(&out, format_text("%salign", prefix));
        TextLines child = doc_tree(doc->children.data[0], depth + 1);
        append_owned(&out, &child);
        break;
    }
    }
    free(prefix);
    return out;
}
typedef struct {
    int old_line, new_line, deletes, inserts;
    TextLines operations;
} Hunk;
typedef struct {
    Hunk *data;
    int count, capacity;
} Hunks;
TextLines diff_lines(const TextLines *before, const TextLines *after) {
    int n = before->count, m = after->count;
    size_t stride = (size_t)m + 1;
    int *lcs = allocate(((size_t)n + 1) * stride * sizeof *lcs);
    for (int i = n - 1; i >= 0; --i)
        for (int j = m - 1; j >= 0; --j) {
            size_t at = (size_t)i * stride + (size_t)j;
            int down = lcs[at + stride], right = lcs[at + 1];
            lcs[at] = !strcmp(before->data[i], after->data[j]) ? lcs[at + stride + 1] + 1
                      : down > right                           ? down
                                                               : right;
        }
    Hunks hunks = {0};
    int i = 0, j = 0, deletes = 0, inserts = 0;
    while (i < n || j < m) {
        if (i < n && j < m && !strcmp(before->data[i], after->data[j])) {
            ++i;
            ++j;
            continue;
        }
        Hunk hunk = {i, j, 0, 0, {0}};
        while ((i < n || j < m) && !(i < n && j < m && !strcmp(before->data[i], after->data[j]))) {
            if (j == m || (i < n && lcs[((size_t)i + 1) * stride + (size_t)j] >=
                                        lcs[(size_t)i * stride + (size_t)j + 1])) {
                lines_push(&hunk.operations, format_text("-%s", before->data[i++]));
                ++hunk.deletes;
            } else {
                lines_push(&hunk.operations, format_text("+%s", after->data[j++]));
                ++hunk.inserts;
            }
        }
        deletes += hunk.deletes;
        inserts += hunk.inserts;
        if (hunks.count == hunks.capacity) {
            hunks.capacity = hunks.capacity ? hunks.capacity * 2 : 8;
            hunks.data = resize(hunks.data, (size_t)hunks.capacity * sizeof *hunks.data);
        }
        hunks.data[hunks.count++] = hunk;
    }
    TextLines out = {0};
    lines_push(&out, format_text("hunks=%d deleted=%d inserted=%d", hunks.count, deletes, inserts));
    for (int k = 0; k < hunks.count; ++k) {
        Hunk *hunk = &hunks.data[k];
        lines_push(&out, format_text("@@ -%d,%d +%d,%d @@",
                                     hunk->old_line + (hunk->deletes ? 1 : 0), hunk->deletes,
                                     hunk->new_line + (hunk->inserts ? 1 : 0), hunk->inserts));
        append_owned(&out, &hunk->operations);
    }
    free(hunks.data);
    free(lcs);
    return out;
}
